import { app, BrowserWindow, shell, ipcMain, dialog } from 'electron';
import { autoUpdater, UpdateCheckResult, UpdateInfo } from 'electron-updater';
import * as path from 'path';
import * as fs from 'fs';

let mainWindow: BrowserWindow | null = null;

// ... existing createWindow() stays the same ...

function initAutoUpdater(): void {
  // Only packaged apps support auto-update; skip in dev
  if (!app.isPackaged) {
    console.log('[autoUpdater] Skipping in development mode');
    return;
  }

  // (Optional) disable auto-download if you want explicit user consent first:
  // autoUpdater.autoDownload = false;

  // Auto-install on quit once downloaded (default is true)
  autoUpdater.autoInstallOnAppQuit = true;

  // ---- Forward every event to the renderer for UI notifications ----
  autoUpdater.on('checking-for-update', () => {
    mainWindow?.webContents.send('update-status', { event: 'checking-for-update' });
  });

  autoUpdater.on('update-available', (info: UpdateInfo) => {
    mainWindow?.webContents.send('update-status', {
      event: 'update-available',
      version: info.version,
      releaseNotes: info.releaseNotes,
    });
  });

  autoUpdater.on('update-not-available', (info: UpdateInfo) => {
    mainWindow?.webContents.send('update-status', { event: 'update-not-available' });
  });

  autoUpdater.on('download-progress', (progress) => {
    mainWindow?.webContents.send('update-status', {
      event: 'download-progress',
      percent: progress.percent,
      transferred: progress.transferred,
      total: progress.total,
    });
  });

  autoUpdater.on('update-downloaded', (info: UpdateInfo) => {
    mainWindow?.webContents.send('update-status', {
      event: 'update-downloaded',
      version: info.version,
      releaseNotes: info.releaseNotes,
    });
  });

  autoUpdater.on('error', (err: Error) => {
    mainWindow?.webContents.send('update-status', {
      event: 'error',
      message: err?.message ?? String(err),
    });
  });

  // IPC: renderer can request install-and-restart now
  ipcMain.handle('install-update', () => {
    // quitAndInstall() restarts the app after installing
    autoUpdater.quitAndInstall(false, true);
  });

  // IPC: renderer can trigger a manual check
  ipcMain.handle('check-for-updates', async () => {
    try {
      const result: UpdateCheckResult | null = await autoUpdater.checkForUpdates();
      return { success: true, updateAvailable: !!result?.updateInfo };
    } catch (err) {
      return { success: false, message: (err as Error).message };
    }
  });

  // Check for updates on app start (after a short delay to let window load)
  // autoDownload defaults to true, so it downloads automatically when available.
  setTimeout(() => {
    autoUpdater.checkForUpdates().catch((err) => {
      console.error('[autoUpdater] checkForUpdates failed:', err);
    });
  }, 3000);
}

app.whenReady().then(() => {
  createWindow();
  initAutoUpdater(); // <-- add this

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});
```

**Behavior summary:**
- Checks ~3s after startup → if newer version on GitHub Releases, downloads automatically (`autoDownload` default true).
- Emits `update-downloaded` → renderer shows a notification.
- User clicks "Install & restart" → calls `install-update` IPC → `autoUpdater.quitAndInstall(false, true)`.
- If user ignores it, `autoInstallOnAppQuit = true` installs silently when they quit normally.

